------------ import ------------
------------ import ------------

------------ define ------------
local Type = {
    ONE = 1,
    TEN = 10,
}
------------ define ------------

---@class SellActionInput
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field BtnAddTen                     	UnityEngine.RectTransform
---@field BtnMinusTen                   	UnityEngine.RectTransform
---@field BtnMinus                      	UnityEngine.RectTransform
---@field BtnAdd                        	UnityEngine.RectTransform
---@field InputFieldNumber              	TMPro.TMP_InputField
local SellActionInput = Class('SellActionInput')

function SellActionInput:__init()
    self.maxNo = nil
    self.curNo = 1
    self.cb = nil
end

function SellActionInput:__delete()
    self.maxNo = nil
    self.curNo = 1
    self.cb = nil
end

---FreshUI
---@param maxNo number 堆叠数量
---@param curNo number 堆叠数量
function SellActionInput:FreshUI(maxNo, curNo)
    if not isNull(curNo) then
        self.curNo = checkNumber(curNo)
        self.InputFieldNumber.text = tostring(self.curNo)
    else
        self.InputFieldNumber.text = '1'
        self.curNo = 1
    end
    self.maxNo = maxNo
    SetButtonAction(self.BtnAdd, function()
        self:OnAddButtonAction(Type.ONE)
    end)
    SetButtonAction(self.BtnMinus, function()
        self:OnMinusButtonAction(Type.ONE)
    end)
    SetButtonAction(self.BtnAddTen, function()
        self:OnAddButtonAction(Type.TEN)
    end)
    SetButtonAction(self.BtnMinusTen, function()
        self:OnMinusButtonAction(Type.TEN)
    end)
    self.InputFieldNumber.onEndEdit:AddListener(function(num)
        ----输入完成后
        print('--->>>', num)
        local no = checkNumber(num)
        if no <= 0 then no = 1 end
        if no > self.maxNo then no = self.maxNo end
        self.curNo = no
        self.InputFieldNumber.text = tostring(no)
        if self.cb then
            self.cb(self.curNo)
        end
    end)
end

function SellActionInput:SetInputActionEvent( cb )
    self.cb  = cb
end

function SellActionInput:OnAddButtonAction(times)
    local preNo = self.curNo
    if (preNo + times) > self.maxNo then
        self.curNo = self.maxNo
    else
        self.curNo = preNo + times
    end
    self.InputFieldNumber.text = tostring(self.curNo)
    if self.cb then
        self.cb(self.curNo)
    end
end

function SellActionInput:OnMinusButtonAction(times)
    local preNo = self.curNo
    if (preNo - times) < 1 then
        self.curNo = 1
    else
        self.curNo = preNo - times
    end
    self.InputFieldNumber.text = tostring(self.curNo)
    if self.cb then
        self.cb(self.curNo)
    end
end

---GetInputNo
---得到当前的输入的数字
function SellActionInput:GetInputNo()
    return checkNumber(self.curNo)
end

function SellActionInput:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return SellActionInput